layout: default
---
<!-- _layouts/paper_project.html -->
<!-- Academic Project Page Template adapted for Jekyll -->

{% if page._styles %}
<!-- Page/Post style -->
<style type="text/css">
    {
            {
            page._styles
        }
    }
</style>
{% endif %}

<div class="post">
    <!-- Hero Section -->
    <header class="post-header">
        <h1 class="post-title">{{ page.title }}</h1>

        {% if page.authors %}
        <div class="authors">
            {% for author in page.authors %}
            <span class="author-block">
                {% if author.url %}
                <a href="{{ author.url }}" target="_blank">{{ author.name }}</a>
                {% else %}
                {{ author.name }}
                {% endif %}
                {% if author.equal_contrib %}<sup>*</sup>{% endif %}{% unless forloop.last %}, {% endunless %}
            </span>
            {% endfor %}
        </div>
        {% endif %}

        {% if page.affiliations %}
        <div class="affiliations">
            {% for affiliation in page.affiliations %}
            <span class="affiliation">{{ affiliation.name }}{% if affiliation.conference %} • {{ affiliation.conference
                }}{% endif %}</span>{% unless forloop.last %}<br>{% endunless %}
            {% endfor %}
            {% if page.equal_contrib_note %}
            <div class="equal-contrib"><small><sup>*</sup>{{ page.equal_contrib_note }}</small></div>
            {% endif %}
        </div>
        {% endif %}

        {% if page.links %}
        <div class="paper-links">
            {% for link in page.links %}
            <a href="{{ link.url }}" target="_blank" class="btn btn-sm z-depth-0" role="button">
                <i class="{{ link.icon }}"></i> {{ link.name }}
            </a>
            {% endfor %}
        </div>
        {% endif %}
    </header>

    <article class="post-content">

        {% if page.teaser_video %}
        <!-- Teaser Video Section -->
        <div class="teaser-video mb-4">
            <video class="img-fluid rounded z-depth-1"
                poster="{% if page.teaser_video.poster %}{{ page.teaser_video.poster }}{% endif %}" id="teaser-video" {%
                if page.teaser_video.autoplay %}autoplay{% endif %} {% if page.teaser_video.controls %}controls{% endif
                %} {% if page.teaser_video.muted %}muted{% endif %} {% if page.teaser_video.loop %}loop{% endif %}>
                <source src="{{ page.teaser_video.url }}" type="video/mp4">
            </video>
            {% if page.teaser_video.caption %}
            <div class="caption">
                {{ page.teaser_video.caption }}
            </div>
            {% endif %}
        </div>
        {% endif %}

        {% if page.abstract %}","totalLinesInFile":423}

{"contents":"{% comment %}
  Renders one entry from a publications list (site.publications collection
  item or a hash with the same fields).
  Usage: {% include publication-item.html pub=pub %}
{% endcomment %}
{% assign pub = include.pub %}
<li class="pub-item">
  <div class="pub-item__thumb">
    {% if pub.thumbnail %}
      <img src="{{ pub.thumbnail | relative_url }}" alt="Thumbnail figure for {{ pub.title }}" loading="lazy" data-lightbox="{{ pub.thumbnail | relative_url }}">
    {% endif %}
  </div>
  <div class="pub-item__body">
    <div class="pub-item__meta">
      {% if pub.tag %}<span class="tag tag--outline">{{ pub.tag }}</span>{% endif %}
      <span class="pub-item__venue">{{ pub.venue }}{% if pub.year %}, {{ pub.year }}{% endif %}</span>
    </div>
    <h3 class="pub-item__title">
      {% if pub.url %}<a href="{{ pub.url }}">{{ pub.title }}</a>{% else %}{{ pub.title }}{% endif %}
    </h3>
    {% if pub.authors %}<p class="text-muted mono" style="font-size: var(--bs-fs-small)">{{ pub.authors }}</p>{% endif %}
    {% if pub.links %}
      <div class="pub-item__links">
        {% for link in pub.links %}<a href="{{ link.url }}">{{ link.label }}</a>{% endfor %}
      </div>
    {% endif %}
    {% if pub.bibtex %}
      <details>
        <summary>Bib</summary>
        <pre class="mono">{{ pub.bibtex }}</pre>
      </details>
    {% endif %}
  </div>
</li>
